def count_nums(arr):
    """
    Write a function count_nums which takes an array of integers and returns
    the number of elements which has a sum of digits > 0.
    If a number is negative, then its first signed digit will be negative:
    e.g. -123 has signed digits -1, 2, and 3.
    """
    def sum_of_digits(n):
        if n < 0:
            # For negative numbers, extract the first signed digit
            s = abs(n)
            while s >= 10:
                s //= 10
            return -(n % 10) + sum_of_digits(abs(n)) - s
        else:
            # For positive numbers or zero, just sum the digits
            return int(abs(n) % 10) + sum_of_digits(int(abs(n) // 10))

    count = 0
    for num in arr:
        if sum_of_digits(num) > 0:
            count += 1
    return count


# Test cases
print(count_nums([]))  # Expected output: 0
print(count_nums([-1, 11, -11]))  # Expected output: 1
print(count_nums([1, 1, 2]))  # Expected output: 3

