    if n < 2:
        return False
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            return False
    return True

def skjkasdkd(lst):
    """Find the largest prime value in the list and return the sum of its digits."""
    largest_prime = -1
    for num in lst:
        if is_prime(num):
            largest_prime = max(largest_prime, num)

    if largest_prime == -1:
        return 0
    else:
        sum_of_digits = sum(int(digit) for digit in str(largest_prime))
        return sum_of_digits

